INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(10601, '2 Chronicles 8:16', '2 Chronicles', 8, 16, '&nbsp;په هغه وخت کښې د سليمان ټول کارونه پوره شول. د مالِک خُدائ د کور د بنياد نه واخله تر سر ته رسولو پورې د هغۀ ټول کارونه په صحيح طريقې سره سر ته ورسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10602, '2 Chronicles 8:17', '2 Chronicles', 8, 17, '&nbsp;سليمان عصيون‌جابر او ايلات ته لاړو، دا د ادوم په علاقه کښې د بحرِقُلزم په غاړه د سمندرى جهازونو ځايونه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10603, '2 Chronicles 8:18', '2 Chronicles', 8, 18, '&nbsp;حيرام بادشاه د خپلو آفسرانو او د تجربه‌کاره کشتو چلوونکو د مشرۍ لاندې هغۀ له سمندرى جهازُونه ولېږل. هغوئ د سليمان د آفسرانو سره د اوفير مُلک ته جهازُونه بوتلل او سليمان له يې د پينځلسو زرو کلو نه زيات سرۀ زر راوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10604, '2 Chronicles 9:1', '2 Chronicles', 9, 1, '&nbsp;د شيبا مُلک مَلِکه د سليمان شُهرت نه خبر شوه او هغه يروشلم ته راغله چې په مشکلو سوالونو د هغۀ امتحان واخلى. هغې ځان سره يوه لويه ډله راوسته او داسې اوښان يې هم راوستل چې په مصالحو، قيمتى کاڼو او په لوئ مِقدار کښې په سرو زرو باندې بار وُو. هغه سليمان له راغله او چې د هغې په ذهن کښې څۀ هم وُو نو د سليمان سره يې د هغې په حقله خبرې وکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10605, '2 Chronicles 9:2', '2 Chronicles', 9, 2, '&nbsp;سليمان هغې له د ټولو سوالونو جوابونه ورکړل. د هغۀ دپاره داسې يو سوال هم مشکل نۀ وو چې د هغې وضاحت يې ورته نۀ شو کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10606, '2 Chronicles 9:3', '2 Chronicles', 9, 3, '&nbsp;د شيبا مَلِکه د سليمان په حِکمت باندې پوهه شوه او چې هغۀ کوم محل جوړ کړے وو هغه يې وليدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10607, '2 Chronicles 9:4', '2 Chronicles', 9, 4, '&nbsp;د هغۀ په دسترخوان چې کوم خوراک پروت وو، د هغۀ د آفسرانو د اوسېدو کوټې، د هغۀ د محل د نوکرانو اِنتظام او د هغوئ لِباس، د هغۀ ساقيان د هغوئ لِباس او هغه سوزېدونکې نذرانې يې وليدې چې هغۀ د مالِک خُدائ په کور کښې پېش کولې. نو په دې هر څۀ حقه حېرانه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10608, '2 Chronicles 9:5', '2 Chronicles', 9, 5, '&nbsp;نو هغې بادشاه ته ووئيل، ”ما چې په خپل مُلک کښې ستا او ستا د حِکمت په حقله څۀ اورېدلى دى هغه رښتيا دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10609, '2 Chronicles 9:6', '2 Chronicles', 9, 6, '&nbsp;هغوئ چې ما ته څۀ وئيل نو ما په هغې باندې تر هغې پورې يقين نۀ کولو چې راغلم او په خپله مې وليدل. زۀ ستا د نيم حِکمت نه هم خبر نۀ وم. چې خلق څۀ وائى تۀ د هغې نه هم ډېر زيات هوښيار يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10610, '2 Chronicles 9:7', '2 Chronicles', 9, 7, '&nbsp;هغوئ څومره بختور دى چې څوک ستا خِدمت کوى، هغوئ هر وخت ستا په حضور کښې وى او د دې حقدار دى چې ستا د حِکمت خبرې واورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10611, '2 Chronicles 9:8', '2 Chronicles', 9, 8, '&nbsp;د مالِک خُدائ ستا د خُدائ پاک ثناء صِفت دې وى. هغۀ دا ښکاره کړې ده چې هغه ستا نه څومره خوشحاله دے چې تۀ يې بادشاه جوړ کړے يې چې د هغۀ په نوم باندې حکومت وکړې. ځکه چې هغه د خپلو خلقو يعنې بنى اِسرائيلو سره مينه کوى او د همېشه دپاره د هغوئ حِفاظت کول غواړى، هغۀ تۀ د هغوئ بادشاه جوړ کړے يې چې د اِنصاف او صداقت نه کار اخلې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10612, '2 Chronicles 9:9', '2 Chronicles', 9, 9, '&nbsp;هغې چې کومې تُحفې راوړې وې نو هغه يې سليمان بادشاه ته پېش کړې، د څلورو زرو کلو نه زيات سرۀ زر او په يو لوئ مِقدار کښې مصالحې او قيمتى کاڼى. د هغې نه نورې ښې مصالحې نۀ وې کومې چې د شيبا مَلِکې سليمان بادشاه له ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10613, '2 Chronicles 9:10', '2 Chronicles', 9, 10, '&nbsp;د حيرام بادشاه او د سليمان بادشاه سړو چې د اوفير نه سرۀ زر راوړل نو هغوئ د صُندل لرګى او کالى هم راوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10614, '2 Chronicles 9:11', '2 Chronicles', 9, 11, '&nbsp;سليمان دا لرګے د مالِک خُدائ د کور او د خپل محل د پوړو جوړولو دپاره استعمال کړو او موسيقارانو له يې ترې نه بينجو او ربابُونه جوړ کړل. د يهوداه په مُلک کښې د دې نه مخکښې د دې په شان هيڅ هم نۀ وُو ليدلے شوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10615, '2 Chronicles 9:12', '2 Chronicles', 9, 12, '&nbsp;مَلِکه شيبا چې څۀ هم غوښتل نو سليمان بادشاه هغه ورکړل. دا د هغې نه علاوه وُو چې د هغه تُحفو په بدل کښې يې ورکړل کومې چې هغې راوړې وې. بيا هغه او د هغې ډله واپس خپل مُلک ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10616, '2 Chronicles 9:13', '2 Chronicles', 9, 13, '&nbsp;سليمان ته هر کال تقريباً درويشت زره کلو سرۀ زر مِلاوېدل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10617, '2 Chronicles 9:14', '2 Chronicles', 9, 14, '&nbsp;د دې نه علاوه تاجرانو او سوداګرو به هغۀ له محصُول هم ورکولو. د عربو بادشاهانو او د بنى اِسرائيلو د ضِلعو حکمرانانو به هم هغۀ له سرۀ زر او سپين زر راوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10618, '2 Chronicles 9:15', '2 Chronicles', 9, 15, '&nbsp;سليمان دوه سوه لوئ ډالونه جوړ کړل، چې هر يو تقريباً په اوو کلو ټکېدلے شوو سرو زرو باندې پټ وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10619, '2 Chronicles 9:16', '2 Chronicles', 9, 16, '&nbsp;درې سوه يې واړۀ ډالونه جوړ کړل، چې هر يو تقريباً په درېو کلو ټکېدلے شوو سرو زرو باندې پټ وو. هغۀ دا ټول د لبنان د ځنګل په محل کښې کېښودلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10620, '2 Chronicles 9:17', '2 Chronicles', 9, 17, '&nbsp;بادشاه يو لوئ تخت هم جوړ کړے وو چې يوه حِصه يې د هاتى په غاښونو باندې پټه وه او باقى په سوچه سرو زرو باندې پټ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10621, '2 Chronicles 9:18', '2 Chronicles', 9, 18, '&nbsp;د دې تخت شپږ پوړۍ وې چې بره ورختلې وې او يو د پښو کېښودلو چوکۍ ورسره تړلے شوې وه چې په سرو زرو باندې پټ وو. د تخت په هر طرف باندې بازوګان وُو او په هر طرف باندې د ولاړو زمرو بُتان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10622, '2 Chronicles 9:19', '2 Chronicles', 9, 19, '&nbsp;په پوړو باندې د دولسو زمرو مجسمې وې، چې شپږ يو طرف ته وُو او شپږ بل طرف ته وُو. په بله يوه بادشاهۍ کښې هيڅکله هم داسې تخت موجود نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10623, '2 Chronicles 9:20', '2 Chronicles', 9, 20, '&nbsp;د سليمان ټولې پيالۍ د سرو زرو نه جوړې وې او د لبنان د ځنګل د دربار ټول لوښى د سوچه سرو زرو وُو. د سليمان په وخت کښې سپين زر اهم نۀ شول ګڼلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10624, '2 Chronicles 9:21', '2 Chronicles', 9, 21, '&nbsp;بادشاه سره د تجارت دپاره سمندرى جهازُونه وُو، دا جهازُونه د حيرام بادشاه سړو چلول. هر درې کاله پس به د هغۀ جهازُونه راواپس کېدل چې سرۀ زر، سپين زر، د هاتى غاښونه، شادوګان او طاؤسان يې راوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10625, '2 Chronicles 9:22', '2 Chronicles', 9, 22, '&nbsp;سليمان بادشاه په دُنيا کښې د نورو ټولو بادشاهانو نه زيات هوښيار او مالدار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10626, '2 Chronicles 9:23', '2 Chronicles', 9, 23, '&nbsp;خُدائ پاک چې هغۀ له کوم حِکمت ورکړے وو د هغې د اورېدو دپاره به ټولو بادشاهانو د هغۀ سره مشوره کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10627, '2 Chronicles 9:24', '2 Chronicles', 9, 24, '&nbsp;سليمان له به هر يو مېلمه دا تُحفې راوړلې: د سرو زرو او سپينو زرو څيزونه، چُوغې، وسلې، مصالحې، آسونه او قچر. هغوئ تر کالونو پورې داسې کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10628, '2 Chronicles 9:25', '2 Chronicles', 9, 25, '&nbsp;د سليمان بادشاه د خپلو جنګى ګاډو او آسونو دپاره څلور زره د ودرېدو ځايونه هم وُو او دولس زره يې آسونه وُو. څۀ يې په يروشلم کښې ساتلى وُو او باقى نور يې په مختلفو ښارونو کښې مقرر کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10629, '2 Chronicles 9:26', '2 Chronicles', 9, 26, '&nbsp;هغه د فرات سيند د علاقې نه واخله د فلستيانو مُلک او د مِصرى سرحد پورې د ټولو بادشاهانو نه عظيم بادشاه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10630, '2 Chronicles 9:27', '2 Chronicles', 9, 27, '&nbsp;د هغۀ د بادشاهۍ په دوران کښې سپين زر په يروشلم کښې د کاڼو په شان عام وُو او دِيار د يهوداه د غرونو په لمن کښې د عام چِنار په شان ډېر تېر وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10631, '2 Chronicles 9:28', '2 Chronicles', 9, 28, '&nbsp;سليمان د مِصر او د نورو ډېرو مُلکونو نه آسونه راوستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10632, '2 Chronicles 9:29', '2 Chronicles', 9, 29, '&nbsp;د سليمان د اول نه واخله تر آخره پورې باقى پاتې تاريخ د ناتن پېغمبر په تاريخ کښې، د سيلا د اخياه په پېشګويۍ کښې او د عدو پېغمبر په پېشګويۍ کښې ليکلے شوى دى، چې هغه د يربعام زوئ د نباط په حقله هم خبرې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10633, '2 Chronicles 9:30', '2 Chronicles', 9, 30, '&nbsp;سليمان په ټولو بنى اِسرائيلو باندې په يروشلم کښې څلوېښت کاله بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10634, '2 Chronicles 9:31', '2 Chronicles', 9, 31, '&nbsp;هغه مړ شو او د داؤد په ښار کښې ښخ شو او د هغۀ زوئ رحُبعام د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10635, '2 Chronicles 10:1', '2 Chronicles', 10, 1, '&nbsp;رحُبعام شِکم ته لاړو، چرته چې د شمالى بنى اِسرائيل ټول خلق د دې دپاره راغونډ وُو چې هغه بادشاه جوړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10636, '2 Chronicles 10:2', '2 Chronicles', 10, 2, '&nbsp;کله چې د نباط زوئ يربعام څوک چې د سليمان بادشاه نه مِصر ته تښتېدلے وو، دا خبر واورېدو نو هغه کور ته واپس راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10637, '2 Chronicles 10:3', '2 Chronicles', 10, 3, '&nbsp;د شمالى قبيلو خلقو هغه راوغوښتلو او هغوئ ټول په يو ځائ رحُبعام له لاړل او هغۀ ته يې ووئيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10638, '2 Chronicles 10:4', '2 Chronicles', 10, 4, '&nbsp;”ستا پلار په مونږ باندې درانۀ بوجونه اېښى دى. کۀ تۀ دا بوجونه سپک کړې او زمونږ دپاره ژوند آسان کړې، نو مونږ به ستا وفادار خلق شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10639, '2 Chronicles 10:5', '2 Chronicles', 10, 5, '&nbsp;رحُبعام ورته ووئيل، ”ما له په دې مسئله باندې د سوچ کولو دپاره درې ورځې راکړئ. او بيا راشئ.“ نو خلق لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10640, '2 Chronicles 10:6', '2 Chronicles', 10, 6, '&nbsp;رحُبعام بادشاه د هغه بوډاګانو سړو سره مشوره وکړه کومو چې د هغۀ د پلار سليمان د مشيرانو په توګه خِدمت کړے وو. هغۀ ترې نه تپوس وکړو، ”تاسو ما له څۀ مشوره راکوئ چې دې خلقو له څۀ جواب ورکړم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10641, '2 Chronicles 10:7', '2 Chronicles', 10, 7, '&nbsp;هغوئ ورته ووئيل، ”کۀ ته په دې خلقو باندې مِهربانه يې او د عقلمندۍ جواب ورکولو په ذريعه د هغوئ خوشحالولو کوشش وکړې، نو هغوئ به په وفادارۍ سره همېشه ستا خِدمت کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10642, '2 Chronicles 10:8', '2 Chronicles', 10, 8, '&nbsp;خو هغۀ د بوډاګانو سړو مشورې ته غوږ ونۀ نيولو او د هغې په ځائ دے زلمو له لاړو کوم چې ورسره لوئ شوى وُو او اوس هم ورسره وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10643, '2 Chronicles 10:9', '2 Chronicles', 10, 9, '&nbsp;هغۀ ترې نه تپوس وکړو، ”تاسو ما له د څۀ کولو مشوره راکوئ؟ زۀ هغه خلقو ته څۀ ووايم چې هغوئ ما ته وائى چې د هغوئ بوجونه سپک کړم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10644, '2 Chronicles 10:10', '2 Chronicles', 10, 10, '&nbsp;هغوئ جواب ورکړو، ”تا له په کار دى چې هغوئ ته داسې ووائې چې زما کچه ګوته زما د پلار د ملا نه مضبوطه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10645, '2 Chronicles 10:11', '2 Chronicles', 10, 11, '&nbsp;هغوئ ته ووايه چې زما پلار په تاسو باندې درانۀ بوجونه اېښى دى، زۀ به دا نور هم درانۀ کړم. هغۀ تاسو په کوړو وهلئ، خو زۀ به تاسو په داسې کوړو ووهم چې لکه د لړم ټک به ورکوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10646, '2 Chronicles 10:12', '2 Chronicles', 10, 12, '&nbsp;درې ورځې وروستو يربعام او نور ټول خلق رحُبعام بادشاه له راواپس شول، لکه څنګه چې هغۀ هغوئ له حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10647, '2 Chronicles 10:13', '2 Chronicles', 10, 13, '&nbsp;بادشاه د بوډاګانو سړو نصيحت ته غوږ ونۀ نيولو او خلقو ته يې سختې خبرې وکړې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10648, '2 Chronicles 10:14', '2 Chronicles', 10, 14, '&nbsp;هم هغه شان چې څنګه هغه زلمو مشوره ورکړې وه. هغۀ ووئيل، ”زما پلار په تاسو باندې درانۀ بوجونه کېښودل او زۀ به دا نور هم درانۀ کړم. هغۀ تاسو په کوړو وهلئ خو زۀ به تاسو په داسې کوړو ووهم چې لکه د لړم ټک به ورکوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10649, '2 Chronicles 10:15', '2 Chronicles', 10, 15, '&nbsp;دا د مالِک خُدائ، خُدائ پاک مرضى وه چې هغه څۀ وکړى چې څۀ يې د نباط زوئ يربعام ته د سيلا د اخياه پېغمبر په ذريعه فرمائيلى وُو. نو دا ځکه بادشاه خلقو ته هيڅ غوږ ونۀ نيولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10650, '2 Chronicles 10:16', '2 Chronicles', 10, 16, '&nbsp;کله چې خلقو ته پته ولګېده چې بادشاه هغوئ ته غوږ نۀ نيولو، نو هغوئ چغه ووهله، ”داؤد او د هغۀ خاندان مرده باد. هغوئ زمونږ دپاره څۀ کړى دى؟ اے بنى اِسرائيلو، راځئ چې کورونو ته لاړ شُو. رحُبعام پرېږدئ چې د خپل ځان خيال وساتى.“ نو داسې بنى اِسرائيلو بغاوت وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10651, '2 Chronicles 10:17', '2 Chronicles', 10, 17, '&nbsp;او رحُبعام يې صِرف د هغه خلقو بادشاه پرېښودو کوم چې د يهوداه په علاقه کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10652, '2 Chronicles 10:18', '2 Chronicles', 10, 18, '&nbsp;رحُبعام بادشاه ادونرام راوغوښتو، کوم چې د هغه مزدورانو مشر وو چې په زور ترې نه کار اخستے شو، چې هغه بنى اِسرائيلو له لاړ شى، خو هغوئ دے په سنګسارولو مړ کړو. نو په دې باندې رحُبعام سمدستى په خپله جنګى ګاډۍ کښې سور شو او يروشلم ته وتښتېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10653, '2 Chronicles 10:19', '2 Chronicles', 10, 19, '&nbsp;نو هم د هغه وخت نه واخله د بنى اِسرائيل مُلک د شمالى بادشاهۍ خلق د داؤد د شاهى خاندان خِلاف بغاوت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10654, '2 Chronicles 11:1', '2 Chronicles', 11, 1, '&nbsp;کله چې رحُبعام بادشاه يروشلم ته ورسېدو، نو هغۀ د يهوداه او بنيامين د قبيلو نه يو سل او اتيا زره تکړه فوجيان راغونډ کړل. د هغۀ اراده دا وه چې جنګ له لاړ شى او د بنى اِسرائيلو په شمالى قبيلو باندې خپل اختيار بيا بحال کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10655, '2 Chronicles 11:2', '2 Chronicles', 11, 2, '&nbsp;خو د مالِک خُدائ کلام په سمعياه پېغمبر نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10656, '2 Chronicles 11:3', '2 Chronicles', 11, 3, '&nbsp;رحُبعام بادشاه او د يهوداه او بنيامين قبيلو ټولو خلقو له دا پېغام ورکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10657, '2 Chronicles 11:4', '2 Chronicles', 11, 4, '&nbsp;”په خپلو بنى اِسرائيلو باندې حمله مۀ کوئ. ټول کورونو ته لاړ شئ. چې څۀ شوى دى هغه زما مرضى وه.“ نو هغوئ د مالِک خُدائ حُکم ومنلو او د يربعام خِلاف جنګ له لا نۀ ړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10658, '2 Chronicles 11:5', '2 Chronicles', 11, 5, '&nbsp;رحُبعام په يروشلم کښې پاتې شو او د يهوداه او بنيامين دې ښارونو نه يې پاخۀ دېوالونه تاو کړل:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10659, '2 Chronicles 11:6', '2 Chronicles', 11, 6, '&nbsp;بيت‌لحم، ايتام، تقوع،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10660, '2 Chronicles 11:7', '2 Chronicles', 11, 7, '&nbsp;بيت‌صور، شوکو، عدولام،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10661, '2 Chronicles 11:8', '2 Chronicles', 11, 8, '&nbsp;جات، مريسه، زيف،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10662, '2 Chronicles 11:9', '2 Chronicles', 11, 9, '&nbsp;ادورائيم، لکيس، عزيقه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10663, '2 Chronicles 11:10', '2 Chronicles', 11, 10, '&nbsp;صُرعا، ايالون او حبرون.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10664, '2 Chronicles 11:11', '2 Chronicles', 11, 11, '&nbsp;هغۀ د دې ښارونو نه ښۀ پاخۀ دېوالونه تاو کړل او په هر يو باندې يې يو فوجى مشر مقرر کړو او د هر يو دپاره يې د خوراک، زيتُونو تېلو او ميو بندوبست وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10665, '2 Chronicles 11:12', '2 Chronicles', 11, 12, '&nbsp;او ډالونه او نېزې يې پرې کېښودې. نو داسې هغۀ يهوداه او بنيامين د خپل قابو لاندې وساتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10666, '2 Chronicles 11:13', '2 Chronicles', 11, 13, '&nbsp;د بنى اِسرائيلو د ټولو علاقو اِمامان او ليويان د يهوداه جنوبى طرف ته راتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10667, '2 Chronicles 11:14', '2 Chronicles', 11, 14, '&nbsp;ليويانو د څرن زمکې او خپل جائيدادونه پرېښودل او يهوداه او يروشلم ته لاړل، ځکه چې د اِسرائيل بادشاه يربعام او د هغۀ زامنو هغوئ دې ته نۀ پرېښودل چې د مالِک خُدائ د اِمامانو په توګه خِدمت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10668, '2 Chronicles 11:15', '2 Chronicles', 11, 15, '&nbsp;يربعام خپل اِمامان مقرر کړل چې هغوئ په علاقائى عبادتخانو کښې خِدمت کوى چې هلته د هغه چېلو او سخو په شکل د بُتانو عبادت کوى چې کوم هغۀ جوړ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10669, '2 Chronicles 11:16', '2 Chronicles', 11, 16, '&nbsp;د بنى اِسرائيلو د ټولو قبيلو نه کومو خلقو چې د زړۀ د اخلاصه د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک عبادت کول غوښتل نو هغوئ ليويانو پسې يروشلم ته لاړل، د دې دپاره چې هغوئ د مالِک خُدائ د هغوئ د پلار نيکۀ خُدائ پاک ته نذرانې پېش کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10670, '2 Chronicles 11:17', '2 Chronicles', 11, 17, '&nbsp;نو په دې باندې د يهوداه بادشاهى مضبوطه شوه او درې کاله يې د سليمان د زوئ رحُبعام ملګرتيا کوله او هغوئ هم هغه شان ژوند تېرولو لکه څنګه چې د داؤد بادشاه او سليمان بادشاه د حکومت لاندې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10671, '2 Chronicles 11:18', '2 Chronicles', 11, 18, '&nbsp;رحُبعام محلت وادۀ کړه، چې د هغې پلار د داؤد زوئ يريموت وو او د هغۀ مور ابى‌خېل وه، چې د اِلياب لور او د يَسى نمسۍ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10672, '2 Chronicles 11:19', '2 Chronicles', 11, 19, '&nbsp;د هغوئ درې زامن وُو، يعوس، سمرياه او زهم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10673, '2 Chronicles 11:20', '2 Chronicles', 11, 20, '&nbsp;وروستو هغۀ معکه وادۀ کړه چې د ابى‌سلوم لور وه او د هغوئ څلور زامن وُو، ابياه، عتى، زيزا او سلوميت.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10674, '2 Chronicles 11:21', '2 Chronicles', 11, 21, '&nbsp;د رحُبعام ټولې اتلس ښځې او شپېتۀ وينځې وې او هغه د اتۀويشتو زامنو او شپېتو لوڼو پلار وو. هغۀ د خپلو ټولو ښځو او د وينځو نه د معکه سره زياته مينه کوله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10675, '2 Chronicles 11:22', '2 Chronicles', 11, 22, '&nbsp;او په هغۀ باندې د هغې زوئ ابياه د نورو ټولو بچو نه زيات ګران وو، نو په دې وجه هغه يې د دې دپاره خوښ کړو چې د هغۀ نه پس بادشاه جوړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10676, '2 Chronicles 11:23', '2 Chronicles', 11, 23, '&nbsp;رحُبعام د هوښيارتيا نه دومره کار واخستو چې خپل زامن يې د يهوداه او بنيامين د پَخو دېوالونو په ټولو ښارونو کښې مقرر کړل. هغوئ له يې ښۀ ډېر خوراک ورکړو او هغوئ هر يو ته يې ښى ډېرې ښځې وادۀ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10677, '2 Chronicles 12:1', '2 Chronicles', 12, 1, '&nbsp;څنګه چې رحُبعام ته د بادشاهۍ اختيار مِلاو شو، او هغه ډېر قوى شو او قوى لوئ شو، نو هغۀ او د هغۀ ټولو خلقو د مالِک خُدائ قانون پرېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10678, '2 Chronicles 12:2', '2 Chronicles', 12, 2, '&nbsp;د رحُبعام د بادشاهۍ په پينځم کال د مالِک خُدائ سره د بې‌وفايۍ په وجه هغوئ ته سزا مِلاو شوه. د مِصر بادشاه سيساق په يروشلم باندې حمله وکړه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10679, '2 Chronicles 12:3', '2 Chronicles', 12, 3, '&nbsp;چې د هغۀ سره د دولسو سوو جنګى ګاډو لښکر، شپېتۀ زره په آسونو سوارۀ کسان او ډېر فوجيان وُو چې بې‌شمېره وُو، چې په دې کښې د ليبيا، سکى او د ايتهوپيا فوجيان شامل وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10680, '2 Chronicles 12:4', '2 Chronicles', 12, 4, '&nbsp;هغۀ د يهوداه د پَخو دېوالونو والا ښارونه قبضه کړل او د يروشلم پورې وړاندې لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10681, '2 Chronicles 12:5', '2 Chronicles', 12, 5, '&nbsp;سمعياه پېغمبر رحُبعام بادشاه او د يهوداه هغه مشرانو له لاړو کوم چې په يروشلم کښې سيساق نه د تښتېدو دپاره راغونډ شوى وُو. هغۀ هغوئ ته وفرمائيل، ”ستاسو دپاره د مالِک خُدائ پېغام دا دے چې تاسو زۀ مالِک خُدائ پرېښودم نو دا ځکه ما تاسو سيساق ته پرېښودئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10682, '2 Chronicles 12:6', '2 Chronicles', 12, 6, '&nbsp;نو بادشاه او مشرانو په عاجزۍ سره دا ومنله چې هغوئ ګناه کړې ده او هغوئ ووئيل، ”مالِک خُدائ چې څۀ کوى نو هغه صحيح دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10683, '2 Chronicles 12:7', '2 Chronicles', 12, 7, '&nbsp;کله چې مالِک خُدائ دا وليدل نو هغۀ سمعياه ته بيا کلام وکړو او ورته يې وفرمائيل، ”هغوئ خپله ګناه ومنله نو زۀ به هغوئ نۀ تباه کوم. خو چې کله سيساق حمله وکړى، نو د هغوئ لږ کسان به ژوندى پاتې شى. يروشلم ته به زما د غصې پوره پته ونۀ لګى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10684, '2 Chronicles 12:8', '2 Chronicles', 12, 8, '&nbsp;خو سيساق به هغوئ فتح کړى، نو هغوئ ته به زما د خِدمت او د دُنياوى بادشاهانو د خِدمت کولو فرق معلوم شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10685, '2 Chronicles 12:9', '2 Chronicles', 12, 9, '&nbsp;سيساق بادشاه يروشلم ته راغلو او د مالِک خُدائ د کور او د محل نه يې خزانې يوړې. هغۀ هر څۀ يوړل سره د هغه ډالونو چې سليمان بادشاه د سرو زرو نه جوړ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10686, '2 Chronicles 12:10', '2 Chronicles', 12, 10, '&nbsp;د هغې په ځائ رحُبعام د زېړو ډالونه جوړ کړل او د هغه آفسرانو په حواله يې کړل چې هغوئ د محل د دروازو د څوکيدارۍ ذمه وار وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10687, '2 Chronicles 12:11', '2 Chronicles', 12, 11, '&nbsp;هر ځل به چې بادشاه د مالِک خُدائ کور ته تلو، نو څوکيدارانو به ډالونه د ځان سره وړل او بيا به يې واپس جمع کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10688, '2 Chronicles 12:12', '2 Chronicles', 12, 12, '&nbsp;هغۀ خپل ځان مالِک خُدائ ته حواله کړو نو په دې وجه د مالِک خُدائ غصې هغه پوره تباه نۀ کړو او د يهوداه کارونه سم وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10689, '2 Chronicles 12:13', '2 Chronicles', 12, 13, '&nbsp;رحُبعام په يروشلم کښې بادشاهى کوله او د خپلې بادشاهۍ طاقت يې زيات کړو. هغه د يو څلوېښتو کالو وو چې هغه بادشاه شو او هغۀ اوولس کاله په يروشلم بادشاهى وکړه، دا هغه ښار وو چې مالِک خُدائ دا د بنى اِسرائيلو د ټولې علاقې نه د داسې ځائ په توګه خوښ کړے وو چرته به چې د هغۀ عبادت کيږى. د رحُبعام مور نعمه وه چې هغه د عمون د مُلک وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10690, '2 Chronicles 12:14', '2 Chronicles', 12, 14, '&nbsp;نو هغۀ بدکارى کوله، ځکه چې هغۀ د مالِک خُدائ د مرضۍ د معلومولو کوشش نۀ کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10691, '2 Chronicles 12:15', '2 Chronicles', 12, 15, '&nbsp;د رحُبعام د اول نه واخله تر آخره پورې کارنامې او د هغۀ د خاندان حِساب کِتاب د سمعياه پېغمبر په تاريخ کښې او د عدو پېغمبر په تاريخ کښې ملاويږى. رحُبعام او يربعام مسلسل د يو بل خِلاف د جنګ په حالت کښې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10692, '2 Chronicles 12:16', '2 Chronicles', 12, 16, '&nbsp;رحُبعام مړ شو او د داؤد ښار په شاهى اديره کښې ښخ شو او د هغۀ زوئ ابياه د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10693, '2 Chronicles 13:1', '2 Chronicles', 13, 1, '&nbsp;د اِسرائيل د بادشاه يربعام د بادشاهۍ په اتلسم کال، ابياه د يهوداه بادشاه شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10694, '2 Chronicles 13:2', '2 Chronicles', 13, 2, '&nbsp;هغۀ په يروشلم باندې درې کاله بادشاهى وکړه. د هغۀ مور ميکاياه وه چې هغه د جبعه د اورى‌اېل لور وه. د ابياه او يربعام په مينځ کښې جنګ ونښتو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10695, '2 Chronicles 13:3', '2 Chronicles', 13, 3, '&nbsp;ابياه د څلورو لاکو فوجيانو يو لښکر جوړ کړو او يربعام د اتو لاکو فوجيانو سره د هغۀ مقابله وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10696, '2 Chronicles 13:4', '2 Chronicles', 13, 4, '&nbsp;لښکرې د اِفرائيم د غرونو په وطن کښې مِلاو شوې. ابياه بادشاه د صمريم غرۀ ته وختلو او يربعام او اِسرائيل ته يې آواز وکړو او ورته يې ووئيل، ”ما ته غوږ ونيسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10697, '2 Chronicles 13:5', '2 Chronicles', 13, 5, '&nbsp;تاسو ته پته نشته چې مالِک خُدائ د بنى اِسرائيلو خُدائ پاک د داؤد سره يو نۀ ختمېدونکے لوظ وکړو، چې هغۀ او د هغۀ اولاد له يې په اِسرائيل باندې د همېشه دپاره بادشاهى ورکړه؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10698, '2 Chronicles 13:6', '2 Chronicles', 13, 6, '&nbsp;د نباط زوئ يربعام د خپل بادشاه سليمان خِلاف بغاوت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10699, '2 Chronicles 13:7', '2 Chronicles', 13, 7, '&nbsp;بيا د بې‌کاره بدمعاشانو يوه ډله د يربعام سره ملګرې شوه او هغوئ د سليمان زوئ رحُبعام خِلاف په هغه وخت کښې بغاوت وکړو کله چې هغه ډېر وړوکے او ناتجربه‌کاره وو او د هغوئ مقابله يې نۀ شوه کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10700, '2 Chronicles 13:8', '2 Chronicles', 13, 8, '&nbsp;اوس ستاسو اراده دا ده چې د شاهى طاقت خِلاف دې جنګ وشى کوم چې مالِک خُدائ د داؤد اولاد له ورکړے دے. تاسو سره يو لوئ لښکر دے او تاسو سره د سرو زرو هغه سخى دى چې يربعام د دې دپاره جوړ کړى دى چې ستاسو معبودان شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');